import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, it } from 'node:test'
import { buildStatus, callers, verifyRef } from '../docs/improvements/_build-status.mjs'

/**
 * The status file drifted once, and the drift was invisible.
 *
 * `status.md` was generated by a script that computed the tables from
 * `_status-*.json` and then appended a paragraph typed by hand: "the other four
 * are still exported, tested and called by nothing." By the time anyone read it
 * again, three of those four had production callers, one item's guard test had
 * been renamed, and the paragraph said otherwise — because a string literal does
 * not know what the tree contains. The file read as verified and was not.
 *
 * So the generator now derives the narrative and resolves every reference against
 * the tree, and this file is what keeps the committed status.md from going stale
 * the same way:
 *
 *   - the committed status.md equals what the generator produces now;
 *   - no ledger reference names a file that does not exist;
 *   - the scanner that decides "called by nothing" actually finds callers — the
 *     canary below is the point. A probe that returns [] for both "no callers"
 *     and "I never ran" would report every module as uncalled, or none.
 */

const ROOT = path.resolve(new URL('..', import.meta.url).pathname)

describe('enhancement status', () => {
  it('the committed status.md is what the generator produces now', () => {
    const { markdown } = buildStatus({ root: ROOT, write: false })
    const committed = readFileSync(path.join(ROOT, 'docs/improvements/status.md'), 'utf8')
    assert.equal(committed, markdown,
      'docs/improvements/status.md is stale — regenerate with node docs/improvements/_build-status.mjs')
  })

  it('every evidence path and guard name resolves', () => {
    const { brokenRefs } = buildStatus({ root: ROOT, write: false })
    assert.deepEqual(brokenRefs, [],
      `the ledger names files that do not exist:\n  ${brokenRefs.join('\n  ')}`)
  })

  it('the call-site scanner finds a caller that exists, and none where none does', () => {
    // Canary: escalation.js is reached *only* through app.js's `lazy()` helper —
    // no `from`/`import()` names it. A scanner that knows only `from '…'` reports
    // it uncalled, and this test is the only thing that would notice.
    assert.ok(callers('public/workflow/escalation.js', ROOT).length > 0,
      'scanner found no caller for escalation.js — it is loaded via lazy(), and a scanner that misses that is broken')
    // And the converse, so the assertion above is not passed by a scanner that
    // returns a non-empty list for everything.
    //
    // The subject used to be `src/agreement.js`, on the grounds that only tests
    // imported it. ENH-09 gave it a real caller (`src/source-agreement.js`), and
    // then `src/replay.js` held the role until ENH-76 wired it to
    // `src/routes/maintenance.js`. Both times the module stopped being the
    // negative case because the entry it named got shipped — which is the point
    // of the assertion, not a reason to weaken it.
    //
    // `src/index.js` is the current subject, and it is a *stable* one: it is
    // `package.json`'s `"main"`, the barrel a consumer of this package imports
    // from outside the repository. Nothing inside the tree imports it, and
    // nothing ever should — an internal module reaching for the package's own
    // entry point is an import cycle waiting to happen. So the zero here is a
    // fact about the design rather than a gap waiting to be filled, and it will
    // not go stale the next time an entry ships.
    assert.equal(callers('src/index.js', ROOT).length, 0,
      'scanner claims src/index.js has a caller; it is the package entry point, imported from outside the tree')
    // And the boundary the old pattern got wrong, asserted where it is decidable.
    //
    // `agreement.js` is a strict *suffix* of `source-agreement.js`, and the two
    // have different importers: `src/source-agreement.js` imports `agreement.js`,
    // while `src/routes/derived.js` imports `source-agreement.js` and never
    // `agreement.js`. So the derived route must not appear among agreement.js's
    // callers. Under the old unanchored `[^'"]*${stem}` it did — the pattern let
    // the stem match the tail of the longer specifier — which is a scanner
    // reporting a caller that does not exist, and it is the direction that hides
    // the "called by nothing" finding rather than raising a false one.
    //
    // Asserted on the set, not a count: both spellings agree on how many callers
    // `source-agreement.js` has, so only naming the file that must be absent
    // separates them.
    assert.ok(callers('src/source-agreement.js', ROOT).includes('src/routes/derived.js'),
      'scanner found no caller for source-agreement.js — the derived route imports it')
    assert.ok(!callers('src/agreement.js', ROOT).includes('src/routes/derived.js'),
      'scanner matched source-agreement.js against the stem agreement.js — the specifier is not anchored')
    // The other root cause, which anchoring does not fix: two different files
    // that share a basename. `src/upload.js` and `src/routes/upload.js` are
    // separate modules, and each is imported by the other's neighbour with an
    // ordinary relative specifier — `src/routes/upload.js` writes `../upload.js`
    // and `src/route-families.js` writes `./routes/upload.js`. Both are anchored
    // correctly and both end in `upload.js`, so only resolving the specifier
    // against the importing file's directory tells them apart. Stated as the set
    // each module has, because that is the only thing that separates them.
    assert.deepEqual(callers('src/upload.js', ROOT).sort(), ['src/routes/upload.js'],
      'the scanner confused src/upload.js with src/routes/upload.js')
    assert.deepEqual(callers('src/routes/upload.js', ROOT).sort(), ['src/route-families.js'],
      'the scanner confused src/routes/upload.js with src/upload.js')
  })

  it('a reference past the end of its file is rejected', () => {
    assert.equal(verifyRef('src/server.js:999999', ROOT).ok, false)
    assert.equal(verifyRef('src/server.js:1', ROOT).ok, true)
    assert.equal(verifyRef('src/does-not-exist.js', ROOT).ok, false)
  })

  it('a count stated in a shipped item\'s detail matches the set it counts', async () => {
    // `verifyRef` resolves `path:line` and guard names, and for a **shipped**
    // item nothing else reads `detail` — the generator emits it only for open
    // items, so a stale sentence there reaches no rendered document. ENH-29 said
    // "40 record entries plus 6 quarantines" for a `SCHEMA` that holds 66
    // entries, 57 records and 9 quarantines: a hand-typed count of a
    // machine-maintained set, in the one field no check reads.
    //
    // Measured against the live declaration, not grepped. The counts are read
    // out of `detail` only where the sentence names the thing counted, so a
    // figure that is not a count of a tree object (a seeded record total, a
    // test's own tally) is left alone rather than guessed at.
    const { SCHEMA, QUARANTINE_SOURCES } = await import('../src/store.js')
    const entries = [...SCHEMA]
    const quarantines = entries.filter((e) => e.kind === 'quarantine').length
    // The predicate is a subset check on itself, so prove it partitions: if
    // `kind` were renamed, every entry would fall to one side and the two
    // figures would still sum, hiding the break.
    assert.ok(quarantines > 0 && quarantines < entries.length,
      `the SCHEMA kind predicate matched ${quarantines} of ${entries.length} — it is wrong, not the ledger`)
    assert.equal(quarantines, QUARANTINE_SOURCES.length,
      'the quarantine entries no longer correspond one-to-one with QUARANTINE_SOURCES')

    // The sentence must state the figures the tree holds. `[^.]*` keeps the
    // match inside the clause, so "66" has to be the number attached to
    // "entries" rather than any 66 elsewhere in the paragraph.
    const detail = ledgerItem('ENH-29')
    assert.match(detail, new RegExp(`\\b${entries.length}\\b[^.]*entr`),
      `ENH-29's detail does not state ${entries.length} entries — it says the tree holds something else`)
    assert.match(detail, new RegExp(`\\b${quarantines}\\b[^.]*quarantines`),
      `ENH-29's detail does not state ${quarantines} quarantines`)
  })
})

/** One ledger item by id, read from whichever group file holds it. */
function ledgerItem(id) {
  for (const g of ['a', 'b', 'c', 'de']) {
    const file = path.join(ROOT, `docs/improvements/_status-${g}.json`)
    const item = JSON.parse(readFileSync(file, 'utf8')).items.find((i) => i.id === id)
    if (item) return item.detail
  }
  throw new Error(`no ledger item ${id} — this test names an item the register does not hold`)
}
